const t={ui:{fig:"Fig. 4",title:"Cerniera centrata",svgLabel:"Un disegno isometrico di come cucire una cerniera centrata in una cucitura: la cucitura cucita fino al segno del fermo in basso, con la fermatura, l'apertura imbastita con il punto più lungo e la cucitura aperta con il ferro; la cerniera a faccia in giù sui margini, i denti sulla linea di cucitura; cucita sul dritto con il piedino per cerniere lungo i due lati e di traverso in basso, nella stessa direzione; poi l'imbastitura scucita, così i due bordi piegati si incontrano sopra i denti.",prev:"Passo precedente",dot:(i,a)=>i?`Passo ${i}: ${a}`:a,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(i,a)=>`Passo ${i} di ${a}`,machine:i=>`Macchina: ${i.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Guarda attraverso la stoffa",putTogether:"Torna alla stoffa",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE"},stitches:{straight:"Punto dritto",basting:"Punto più lungo"},labels:{rightSides:"dritto contro dritto",markStop:"segna il fermo in basso",toMark:"cucitura fino al segno",backstitch:"fermatura",baste:"imbastisci: punto più lungo",openOut:"apri",wrongUp:"rovescio sopra",pressOpen:"apri la cucitura col ferro",faceDown:"zip a faccia in giù",teethOnSeam:"denti sulla cucitura",allowancesOnly:"appunta solo ai margini",rightUp:"dritto sopra",belowStop:"di traverso, sotto il fermo",pivot:"gira, ago abbassato",needleDown:"ago abbassato, piedino su",movePull:"cursore dietro il piedino",otherSide:"l'altro lato",sameWay:"nella stessa direzione",unpick:"scuci l'imbastitura",meet:"i bordi si incontrano"},steps:[{title:"Cerniera centrata",text:"I due bordi piegati della cucitura si incontrano sopra i denti della zip; una cucitura corre lungo ogni lato e di traverso in basso. Tocca per guardare attraverso la stoffa."},{title:"Dritto contro dritto",text:"Metti i due pezzi dritto contro dritto. Appoggia la zip lungo la linea di cucitura e segna dov'è il suo fermo in basso: lì finisce l'apertura per la zip.",details:["Prima rifinisci i bordi della cucitura, così non si sfilacciano.","Metti i due pezzi dritto contro dritto, i bordi pari, e fissali con le clip.","Appoggia la zip lungo la linea di cucitura e segna la linea di cucitura al suo fermo in basso: lì finisce l'apertura per la zip."]},{title:"La cucitura fino al segno",text:"Cuci la cucitura con il punto normale fino al segno e fai lì la fermatura, così la cucitura tiene dove finisce la zip.",details:["Cuci la cucitura con il punto normale, sulla linea di cucitura, fino al segno.","Fai la fermatura al segno: dove finisce la zip la cucitura non deve aprirsi."]},{title:"Imbastisci l'apertura",text:"Imposta il punto più lungo e chiudi l'apertura sulla stessa linea di cucitura, dal segno fino al bordo superiore. Questa imbastitura alla fine si scuce.",details:["Imposta sulla macchina il punto più lungo: è un'imbastitura, dopo la scuci.","Chiudi l'apertura sulla stessa linea di cucitura, dal segno fino al bordo superiore.","L'imbastitura tiene chiusa l'apertura mentre cuci la zip."]},{title:"Apri la cucitura col ferro",text:"Apri i pezzi, girali con il rovescio sopra e apri i margini di cucitura con il ferro, uno per lato, lungo tutta la cucitura.",details:["Apri i pezzi e girali con il rovescio sopra.","Apri i margini di cucitura con il ferro, uno per lato, lungo tutta la cucitura, anche la parte imbastita."]},{title:"La zip a faccia in giù",text:"Appoggia la zip a faccia in giù sui margini di cucitura, i denti proprio sulla linea di cucitura, e appuntala solo ai margini.",details:["Appoggia la zip a faccia in giù sui margini di cucitura aperti.","I denti proprio sulla linea di cucitura, il fermo in basso al segno.","Appunta il nastro della zip solo ai margini di cucitura, non ai pezzi sotto."]},{title:"Un lato",text:"Gira il lavoro con il dritto sopra. Con il piedino per cerniere cuci un lato e di traverso in basso, sotto il fermo, girando all'angolo con l'ago abbassato, attraverso tutti gli strati.",details:["Gira il lavoro con il dritto sopra: la zip è sotto, i suoi denti sotto la linea di cucitura.","Monta il piedino per cerniere: con lui l'ago cuce vicino alla zip.","Cuci lungo un lato, sempre alla stessa distanza dalla cucitura, e di traverso in basso, sotto il fermo: mai sopra il fermo.","All'angolo fermati con l'ago abbassato nella stoffa, alza il piedino, gira il lavoro e continua."]},{title:"Sposta il cursore",text:"Quando il cursore dà fastidio, fermati con l'ago abbassato, alza il piedino e fai scorrere il cursore dietro il piedino. Abbassa il piedino e finisci il lato con il piedino per cerniere.",details:["Qualche punto prima del cursore fermati, con l'ago abbassato nella stoffa.","Alza il piedino e fai scorrere il cursore dietro il piedino, dietro l'ago.","Abbassa il piedino e finisci il lato con il piedino per cerniere."]},{title:"L'altro lato",text:"Cuci l'altro lato e l'altra metà di traverso in basso allo stesso modo con il piedino per cerniere, girando all'angolo con l'ago abbassato, nella stessa direzione del primo lato.",details:["Cuci lungo l'altro lato, alla stessa distanza dalla cucitura, e l'altra metà di traverso, sotto il fermo.","All'angolo gira con l'ago abbassato.","Cuci i due lati nella stessa direzione."]},{title:"Scuci l'imbastitura",text:"Scuci l'imbastitura sopra la zip e stira. I due bordi piegati si incontrano sopra i denti, la zip si vede appena.",details:["Scuci i punti dell'imbastitura sopra la zip.","Stira sul dritto: i due bordi piegati si incontrano sopra i denti."]}],legend:[{title:"Stoffa",text:"due pezzi uniti da una cucitura · i bordi piegati si incontrano sopra i denti"},{title:"Cucitura della zip",text:"lungo i due lati e di traverso sotto il fermo · alla stessa distanza dalla cucitura"},{title:"Cucitura",text:"sotto la zip, con la fermatura al segno"},{title:"Zip",text:"a faccia in giù sotto la cucitura, i denti sulla linea di cucitura"}]};export{t as default};
